      </div>
    </div>
  </div>
</div>---
import SkillCardItem from "./SkillCardItem.astro";
import { Icon } from "astro-icon/components";
import type { SkillsLine } from "@/types";

interface Props {
  skillLine: SkillsLine;
  reverse?: boolean;
}

const { skillLine, reverse = false } = Astro.props;
const { title, logo, skills } = skillLine;

// Multiply the array to guarantee it fills ultra-wide screens.
// If the base array has 5 items, this makes 15 items per track.
const fillTrack = (skillArray: any[]) => [
  ...skillArray,
  ...skillArray,
  ...skillArray,
];
---

<div
  class="flex flex-col group border border-primary/50 hover:border-primary transition-all duration-500 rounded-xl gap-10 py-6 w-full relative overflow-hidden"
>
  <div
    class="absolute inset-0 pointer-events-none bg-gradient-to-br from-primary/10 via-transparent to-primary/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500 z-0"
  >
  </div>
  <div
    class="absolute inset-y-0 left-0 w-24 md:w-40 bg-gradient-to-r from-bg to-transparent z-10 pointer-events-none"
  >
  </div>
  <div
    class="absolute inset-y-0 right-0 w-24 md:w-40 bg-gradient-to-l from-bg to-transparent z-10 pointer-events-none"
  >
  </div>

  <div class="flex gap-4 items-center px-8 md:px-10 relative z-20">
    {
      logo ? (
        <div class="flex items-center justify-center p-1 rounded-xl border border-white/10 text-primary drop-shadow-[0_0_8px_var(--color-primary)]">
          <Icon name={logo} class="w-11 h-11 " />
        </div>
      ) : (
        <div class="flex items-center justify-center w-12 h-12 rounded-xl bg-white/5 border border-white/10 text-3xl font-bold text-primary drop-shadow-[0_0_8px_var(--color-primary)]">
          {title.charAt(0)}
        </div>
      )
    }
    <h3 class="font-bold text-xl md:text-4xl text-gray-300">{title}</h3>
  </div>

  <div class="flex flex-col gap-6 relative z-20">
    {
      skills.map((skill, index) => {
        let isRowReversed = reverse;
        if (index % 2 === 0) {
          isRowReversed = !isRowReversed;
        }

        const animationClass = isRowReversed
          ? "animate-marquee-reverse"
          : "animate-marquee";

        // Create the massive array for the track
        const trackItems = fillTrack(skill);

        return (
          // Parent flex container holding the two identical tracks.
          // gap-6 connects the end of Track 1 to the start of Track 2 seamlessly.
          <div class="flex overflow-hidden w-full group/row">
            {/* Track 1 */}
            <div
              class={`flex w-max shrink-0 gap-6 pr-6 ${animationClass} group-hover/row:[animation-play-state:paused]`}
            >
              {trackItems.map((skillLine) => (
                <SkillCardItem
                  name={skillLine.name}
                  expertise={skillLine.expertise}
                  logo={skillLine.logo}
                />
              ))}
            </div>

            {/* Track 2 (Identical mirror for the loop) */}
            <div
              aria-hidden="true"
              class={`flex w-max shrink-0 gap-6 pr-6 ${animationClass} group-hover/row:[animation-play-state:paused]`}
            >
              {trackItems.map((skillLine) => (
                <SkillCardItem
                  name={skillLine.name}
                  expertise={skillLine.expertise}
                  logo={skillLine.logo}
                />
              ))}
            </div>
          </div>
        );
      })
    }
  </div>
</div>---
import BaseLayout from "@/layouts/BaseLayout.astro";
import { getCollection } from "astro:content";

const blogs = (await getCollection("blogs")).sort(
  (a, b) =>
    new Date(b.data.pubDate).valueOf() - new Date(a.data.pubDate).valueOf(),
);

// Group blogs by year
const blogsByYear = blogs.reduce(
  (acc, blog) => {
    const year = new Date(blog.data.pubDate).getFullYear().toString();
    if (!acc[year]) {
      acc[year] = [];
    }
    acc[year].push(blog);
    return acc;
  },
  {} as Record<string, typeof blogs>,
);

// Sort years in descending order (newest first)
const years = Object.keys(blogsByYear).sort(
  (a, b) => parseInt(b) - parseInt(a),
);
---

<BaseLayout>
  <div class="px-6 md:px-20 mt-15 max-w-7xl mx-auto mb-20">
    <div class="flex flex-col justify-center text-gray-200 gap-4 mb-6">
      <h1 class="font-bold text-4xl font-pixel text-primary/90">Blog</h1>
      <p class="w-full md:w-[60%] text-justify text-gray-300 leading-8">
        Welcome to my blog domain where I share personal stories about things
        I've learned, projects I'm hacking on and just general findings.
      </p>
    </div>

    <div class="flex flex-col gap-10">
      {
        years.map((year) => (
          <div class="flex flex-col gap-6">
            <div class="flex items-center gap-4 mt-4">
              <h2 class="text-3xl font-bold font-pixel text-gray-200">
                {year}
              </h2>
              <div class="flex-grow h-px bg-white/10 rounded-full" />
            </div>

            <div class="grid grid-cols-1 gap-6">
              {blogsByYear[year].map((blog) => (
                <a
                  href={`/blog/${blog.id}`}
                  class="group flex flex-col gap-3 p-6 rounded-2xl bg-white/2 border border-white/10 hover:border-primary/50 transition-all duration-300 hover:bg-white/[0.04] bg-transparent hover:shadow-none"
                >
                  <h3 class="text-2xl font-pixel font-bold text-primary/80 group-hover:text-primary transition-colors">
                    {blog.data.title}
                  </h3>
                  <p class="text-sm text-gray-400">
                    {new Date(blog.data.pubDate).toLocaleDateString("en-US", {
                      // month: "long",
                      // day: "numeric",
                      dateStyle: "long",
                    })}
                  </p>
                  <p class="text-gray-300 line-clamp-3">
                    {blog.data.description}
                  </p>
                  {blog.data.tags && (
                    <div class="flex gap-2 mt-2">
                      {blog.data.tags.map((tag: string) => (
                        <span class="text-xs font-bold px-3 py-1 rounded-full bg-primary/10 text-primary/80 border border-primary/20">
                          #{tag}
                        </span>
                      ))}
                    </div>
                  )}
                </a>
              ))}
            </div>
          </div>
        ))
      }
    </div>
  </div>
</BaseLayout>*.xml
