          class="flex gap-2 items-center rounded-lg border p-2 bg-white/3 backdrop-blur-md"
        >
          <Icon name="mdi:clock" size={24} />
          <p class="text-white font-bold">{jobType}</p>
        </div>
      </div>

      <div class="flex items-center flex-wrap gap-4 mt-5">
        <!-- <h1 class="font-bold text-2xl">Tools:</h1> -->
        <div title="tools" class="flex gap-2">
          <Icon name="mdi:tools" class="w-10 h-10" />
          <span class="text-2xl font-bold">:</span>
        </div>
        <div class="flex items-center flex-wrap gap-2">
          {
            tools &&
              tools.map((tool) => {
                const { name, logo } = tool;
                return (
                  <>
                    {logo ? (
                      <div
                        title={name}
                        class="flex  gap-2 items-center justify-center p-2 rounded-lg border border-gray-200/15 hover:bg-primary/10 hover:border-primary transition-all duration-300 hover:-translate-y-2 text-gray-100"
                      >
                        <Icon name={logo} class="w-8 h-8 md:w-10 md:h-10 " />
                      </div>
                    ) : (
                      <div class="flex items-center justify-center w-12 h-12 rounded-xl bg-white/5 border border-white/10 text-3xl font-bold text-primary drop-shadow-[0_0_8px_var(--color-primary)]">
                        {name.charAt(0)}
                      </div>
                    )}
                  </>
                );
              })
          }
        </div>
      </div>

      <ul class="list-none text-gray-100 flex flex-col gap-5 mt-0">
        {
          points.map((p) => (
            <li class="flex items-start gap-3 group/item text-base md:text-lg">
              <Icon
                name="weui:arrow-filled"
                class="w-8 h-8 text-primary shrink-0 mt-0.5 group-hover/item:translate-x-2 transition-all"
              />
              <span
                class="text-gray-300 group-hover/item:text-gray-50 transition-colors leading-relaxed text-justify"
                set:html={parseBold(p)}
              />
            </li>
          ))
        }
      </ul>
    </div>
  </div>

  <div
    class="timeline-dot absolute left-0 top-10 transform -translate-x-1/2 w-4 h-4 rounded-full bg-slate-700 shadow-none transition-all duration-500 ease-out"
  >
  </div>
</div>

<script>
  const setupCardsObserver = () => {
    const observer = new IntersectionObserver(
      (entries, observerInstance) => {
        entries.forEach((entry) => {
          // Find the specific dot inside the card that is currently intersecting
          const dot = entry.target.querySelector(".timeline-dot");

          if (entry.isIntersecting) {
            // 1. Show the card
            entry.target.classList.remove("opacity-0", "translate-y-16");
            entry.target.classList.add("opacity-100", "translate-y-0");

            // 2. Turn ON the dot's glow
            if (dot) {
              dot.classList.remove("bg-slate-700", "shadow-none");
              dot.classList.add(
                "bg-primary",
                "shadow-[0_0_25px_var(--color-primary)]",
              );
            }

            // 3. Unobserve the card so the animation only happens once
            observerInstance.unobserve(entry.target);
          }
        });
      },
      {
        threshold: 0.2,
        rootMargin: "0px 0px -10% 0px",
      },
    );

    const cards = document.querySelectorAll(".reveal-card");
    cards.forEach((card) => observer.observe(card));
  };

  setupCardsObserver();
  document.addEventListener("astro:page-load", setupCardsObserver);
</script>---
