const resumeEndpoint: string =
  "https://bucket.senop.dev/Seno%20Pamungkas%20Rahman%20-%20CV%20(main).pdf";

const blogEndpoint: string = "/blog";
---

<section
  id="home"
  class="min-h-screen relative flex flex-col justify-center items-center text-center"
>
  <ParticlesBackground
    id="home-particles"
    options={{
      fullScreen: {
        enable: false,
      },
      background: {
        color: { value: "transparent" },
      },
      fpsLimit: 120,
      interactivity: {
        detectsOn: "window",
        events: {
          onHover: {
            enable: true,
            parallax: {
              enable: true,
              force: 60,
              smooth: 10,
            },
          },
        },
      },
      particles: {
        color: { value: "#0ffe7a" },
        links: {
          color: "#ffffff",
          distance: 150,
          enable: true,
          opacity: 0.1,
          width: 1,
        },
        move: {
          enable: true,
          speed: 1,
          direction: "none",
          outModes: { default: "bounce" },
        },
        number: {
          density: { enable: true, width: 800, height: 800 },
          value: 40, // Adjust for more/fewer particles
        },
        opacity: { value: 0.4 },
        shape: { type: "circle" },
        size: { value: { min: 1, max: 3 } },
      },
      detectRetina: true,
    }}
    client:idle
  />

  <div class="w-[90%] lg:w-[60%] max-w-5xl flex flex-col gap-9">
    {/* Main Title Section */}
    <div class="relative flex flex-col gap-10 text-center pb-4">
