      >
      </div>
      <div class="relative z-10 font-bold">
        <h1 class="text-gray-200 text-5xl md:text-7xl mb-12">
          Hi, I'm <span class="text-gradient">Seno Pamungkas Rahman</span>
        </h1>
        <h2 class="text-3xl md:text-5xl text-gray-300/90 mt-4">
          <TypewriterText client:load />
        </h2>
      </div>
    </div>

    <div
      class="w-80 h-[1px] bg-gradient-to-r from-transparent via-primary/50 to-transparent mx-auto"
    >
    </div>

    {/* Description Section */}
    <!-- <p class="text-gray-50 text-xl md:text-2xl tracking-wider leading-relaxed"> -->
    <!--   An avid software engineer with a zest for front-end, back-end, AI, and -->
    <!--   cloud technologies. Passionate about exploring new tech frontiers, I blend -->
    <!--   creativity with technical skill in every project, pushing the boundaries -->
    <!--   of software innovation -->
    <!-- </p> -->
    <p class="text-gray-50 text-xl md:text-2xl tracking-wider leading-relaxed">
      A Platform and Full-Stack Software Engineer specializing in cloud-native
      infrastructure, systems programming, and scalable web applications. From
      architecting high-concurrency Go tools and managing Kubernetes
      environments to building dynamic frontend experiences, I bridge the gap
      between robust backend operations and seamless user interactions.
    </p>

    {/* Buttons Section */}
    <div class="flex gap-10 items-center justify-center mt-5">
      <a
        href={resumeEndpoint}
